import{_ as t,o,c as a,ak as i}from"./chunks/framework.PDII-gUq.js";const r="/projects/H5S/en/latest/assets/image1.DdfjWywW.webp",s="/projects/H5S/en/latest/assets/image2.CNstAxWc.webp",_=JSON.parse('{"title":"4. Expansion Course-Import Custom Music","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.Expansion_Course_Import_Custom_Music.md","filePath":"docs/4.Expansion_Course_Import_Custom_Music.md"}'),n={name:"docs/4.Expansion_Course_Import_Custom_Music.md"};function c(l,e,p,u,m,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_4-expansion-course-import-custom-music" tabindex="-1">4. Expansion Course-Import Custom Music <a class="header-anchor" href="#_4-expansion-course-import-custom-music" aria-label="Permalink to &quot;4. Expansion Course-Import Custom Music&quot;">​</a></h1><h2 id="_4-1-objective" tabindex="-1">4.1 Objective <a class="header-anchor" href="#_4-1-objective" aria-label="Permalink to &quot;4.1 Objective&quot;">​</a></h2><p>In this section, you will learn how to read from and write to the robot&#39;s built-in TF card in order to play custom music while executing an action group.</p><h2 id="_4-2-implementation" tabindex="-1">4.2 Implementation <a class="header-anchor" href="#_4-2-implementation" aria-label="Permalink to &quot;4.2 Implementation&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>During the procedure, it requires removing the four screws on the robot&#39;s back cover. After completing the operation, re-install the back cover.</li><li>If you are using a new TF card, ensure that its capacity does not exceed 32 GB.</li></ul></div><p>(1) Rename your custom audio file, and the controller supports MP3/WAV formats. The filename format is: [Four-digit Action Group Number] + [Song Name] with no spaces between the number and the name. For example, if Action Group 40 will be paired with the song The Most Dazzling Folk Style, rename the file to: 0040TheMostDazzlingFolkStyle If the action group number is less than four digits, pad it with leading zeros.</p><p>(2) Locate and remove the TF card from the controller, please refer to the diagram below for position.</p><img loading="lazy" height="766" width="820" src="'+r+'" class="common_img" style="width:500px;"><p>(3) To transfer the audio file, first insert the TF card into a card reader, then copy the renamed audio file into the <strong>&quot;MP3&quot;</strong> folder on the TF card. After importing, the TF card should contain files exactly as shown in the example below.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Files placed in other folders or in subfolders within the <strong>&quot;MP3&quot;</strong> folder cannot be read correctly.</p></div><img loading="lazy" height="269" width="417" src="'+s+'" class="common_img"><p>(4) Re-insert the TF card into the control board and re-attach the back cover. Run Action Group 40 to enjoy the robot&#39;s music and dance performance.</p>',12)])])}const f=t(n,[["render",c]]);export{_ as __pageData,f as default};
